RCC_CR |= RCC_CR_HSEON;        /* bit16 */
uint32_t timeout = 0x00100000UL;
while (((RCC_CR & RCC_CR_HSERDY) == 0UL)
       && (timeout-- != 0UL)) { }
if ((RCC_CR & RCC_CR_HSERDY) == 0UL) {
    RCC_CR &= ~RCC_CR_HSEON;    /* 关掉白耗的电 */
    g_clock_status = 1;         /* 回退 HSI */
}

if (pll_params_from_hse(HSE_VALUE_HZ, &m, &n, &p, &q) != 0)
    return -1;                    /* 参数不合法就不硬切 */
g_pll_m = m; g_pll_n = n; g_pll_p = p; g_pll_q = q;

~ HSE_VALUE_HZ 是编译期常数，
~ 整条算术在编译期就出结果了。

RCC_CFGR = (RCC_CFGR & ~RCC_CFGR_SW) | 0x2UL;  /* SW=10b */
uint32_t timeout = 0x00100000UL;
while (((RCC_CFGR & RCC_CFGR_SWS) != RCC_CFGR_SWS_PLL)
       && (timeout-- != 0UL)) { }
if ((RCC_CFGR & RCC_CFGR_SWS) != RCC_CFGR_SWS_PLL) {
    g_clock_status = 1;      /* 没回执，就当没切成 */
    SystemCoreClock = 16000000UL;
}

/* 关键：传进去的是回读出来的 HCLK，不是猜的 */
systick_init(g_clock_tree[1]);

SysTick_LOAD = hclk_hz / 1000UL - 1UL;
SysTick_VAL  = 0;
SysTick_CTRL = 0x7UL;   /* ENABLE|TICKINT|CLKSOURCE */

